// Compiled only into the netstandard2.1 build. The project removes this file from
// every other target, the way dotnet/runtime conditions its own polyfills, so the
// rule lives in the project file and not in a #if here.
//
// This file holds only the framework APIs netstandard2.1 lacks that this project
// calls. The compiler-required types (IsExternalInit and
// CallerArgumentExpressionAttribute) are generated by PolySharp; see
// Directory.Build.props.

namespace Hyperbee.Json.Internal;

/// <summary>
/// Span members that newer targets have in box.
/// </summary>
/// <remarks>
/// <see cref="MemoryExtensions"/> gained <c>Contains</c> after netstandard2.1 was
/// cut. Compiled only for netstandard, so on targets that have the framework
/// extension there is never a second candidate. <c>IndexOf</c> is the vectorized
/// primitive the framework <c>Contains</c> is itself built on.
/// </remarks>
internal static class SpanShimExtensions
{
    public static bool Contains<T>( this Span<T> span, T value ) where T : IEquatable<T>
        => span.IndexOf( value ) >= 0;

    public static bool Contains<T>( this ReadOnlySpan<T> span, T value ) where T : IEquatable<T>
        => span.IndexOf( value ) >= 0;
}
